import { Component, Element, h, Host, Listen, Prop } from '@stencil/core';
import { EmbeddedButtonSize } from '../../types';
import { AriaAttributes, extractAriaAttributes } from '../../utils/a11y-helper';

@Component({
  tag: 'groupui-embedded-button',
  styleUrl: 'embedded-button.scss',
  shadow: true,
})
export class EmbeddedButton {
  /**
   * size of embedded button. Provided values are 'xs' and 'xxs'
   */
  @Prop({ reflect: true }) readonly size: EmbeddedButtonSize = 'xs';

  /**
   * icon name e.g. 'clock-24'. Use the following matching icon sizes for the different button sizes: xs: 24px, xxs: 16px
   */
  @Prop({ reflect: true }) readonly icon: string;

  /**
   * sets a custom icon source e.g. '...path/clock-24.svg', overrides icon property if both are set
   */
  @Prop({ reflect: true }) readonly iconSource: string;

  /**
   * disabled status of the embedded button
   */
  @Prop({ reflect: true }) readonly disabled: boolean = false;

  @Element() host: HTMLElement;

  private ariaAttributes: AriaAttributes;

  componentWillLoad() {
    this.ariaAttributes = extractAriaAttributes(this.host);
  }

  @Listen('keydown')
  onKeyDown(event: KeyboardEvent) {
    if (event.code === 'Enter' || event.code === 'Space') {
      event.preventDefault();
    }
  }

  @Listen('keyup')
  onKeyUp(event: KeyboardEvent) {
    if (event.code === 'Enter' || event.code === 'Space') {
      this.host.dispatchEvent(new window.Event('click', { bubbles: true }));
    }
  }

  @Listen('click', { capture: true })
  captureClick(event) {
    if (this.disabled) {
      event.stopPropagation();
    }
  }

  render() {
    return (
      <Host>
        <button tabIndex={0} aria-label="Icon" {...this.ariaAttributes} disabled={this.disabled}>
          <groupui-icon name={this.icon} src={this.iconSource} aria-hidden="true" />
        </button>
      </Host>
    );
  }
}
